"use client"
import { useMemo, useState } from "react"
import { SearchIcon, FileSearchIcon } from "lucide-react"
import { Button } from "@atlas/ui-web/primitives/Button/Button"
import { Input } from "@atlas/ui-web/primitives/Input/Input"
import { Checkbox } from "@atlas/ui-web/primitives/Checkbox/Checkbox"
import { Badge } from "@atlas/ui-web/primitives/Badge/Badge"
import { Skeleton } from "@atlas/ui-web/primitives/Skeleton/Skeleton"
import {
  Select,
  SelectTrigger,
  SelectValue,
  SelectContent,
  SelectItem,
} from "@atlas/ui-web/primitives/Select/Select"
import {
  Table,
  TableHeader,
  TableBody,
  TableRow,
  TableHead,
  TableCell,
} from "@atlas/ui-web/primitives/Table/Table"
import {
  AlertDialog,
  AlertDialogContent,
  AlertDialogTitle,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogCancel,
  AlertDialogAction,
} from "@atlas/ui-web/compositions/AlertDialog/AlertDialog"
import {
  INVOICES_INITIAL,
  STATUS_BADGE,
  STATUS_FILTERS,
  formatAmount,
  formatDue,
  type Invoice,
  type PreviewState,
  type StatusFilter,
} from "../data"

const PREVIEWS: { key: PreviewState; label: string }[] = [
  { key: "data", label: "Data" },
  { key: "loading", label: "Loading" },
  { key: "empty", label: "No results" },
]

const SKELETON_ROWS = [0, 1, 2, 3, 4]

export function Invoices() {
  const [invoices, setInvoices] = useState<Invoice[]>(INVOICES_INITIAL)
  const [query, setQuery] = useState("")
  const [status, setStatus] = useState<StatusFilter>("all")
  const [selected, setSelected] = useState<Set<string>>(new Set())
  const [confirmOpen, setConfirmOpen] = useState(false)
  const [preview, setPreview] = useState<PreviewState>("data")

  const loading = preview === "loading"

  const visible = useMemo(() => {
    if (preview === "empty") return []
    const q = query.trim().toLowerCase()
    return invoices.filter(
      (inv) =>
        (status === "all" || inv.status === status) &&
        (q === "" || inv.number.toLowerCase().includes(q) || inv.customer.toLowerCase().includes(q)),
    )
  }, [invoices, query, status, preview])

  // Only rows the user can see are acted on.
  const selectedVisible = visible.filter((inv) => selected.has(inv.id))
  const count = selectedVisible.length
  const allChecked: boolean | "indeterminate" =
    visible.length > 0 && count === visible.length ? true : count > 0 ? "indeterminate" : false

  const toggleAll = (checked: boolean | "indeterminate") =>
    setSelected(checked === true ? new Set(visible.map((inv) => inv.id)) : new Set())

  const toggleRow = (id: string, checked: boolean | "indeterminate") =>
    setSelected((prev) => {
      const next = new Set(prev)
      if (checked === true) next.add(id)
      else next.delete(id)
      return next
    })

  const markPaid = () => {
    const ids = new Set(selectedVisible.map((inv) => inv.id))
    setInvoices((prev) => prev.map((inv) => (ids.has(inv.id) ? { ...inv, status: "Paid" } : inv)))
    setSelected(new Set())
  }

  const deleteSelected = () => {
    const ids = new Set(selectedVisible.map((inv) => inv.id))
    setInvoices((prev) => prev.filter((inv) => !ids.has(inv.id)))
    setSelected(new Set())
  }

  const clearFilters = () => {
    setQuery("")
    setStatus("all")
    setPreview("data")
  }

  const noInvoicesAtAll = invoices.length === 0 && preview !== "empty"

  return (
    <div
      style={{
        display: "flex",
        flexDirection: "column",
        gap: "var(--atlas-spacing-4)",
        paddingInline: "var(--atlas-spacing-4)",
        paddingBlockEnd: "var(--atlas-spacing-6)",
        color: "var(--atlas-foreground)",
        fontFamily: "var(--atlas-font-sans)",
      }}
    >
      <h1
        style={{
          margin: 0,
          fontSize: "var(--atlas-text-h2)",
          fontWeight: "var(--atlas-font-weight-semibold)",
          lineHeight: "var(--atlas-line-height-tight)",
        }}
      >
        Invoices
      </h1>

      {/* Review-only: switch the screen between its states */}
      <div
        role="group"
        aria-label="Preview state (review only)"
        style={{
          display: "flex",
          alignItems: "center",
          gap: "var(--atlas-spacing-2)",
          flexWrap: "wrap",
          padding: "var(--atlas-spacing-2)",
          border: "var(--atlas-border-width-1) dashed var(--atlas-border-strong)",
          borderRadius: "var(--atlas-radius-md)",
        }}
      >
        <span style={{ fontSize: "var(--atlas-text-caption)", color: "var(--atlas-foreground-muted)" }}>
          Preview
        </span>
        {PREVIEWS.map((p) => (
          <Button
            key={p.key}
            size="xs"
            variant={preview === p.key ? "primary" : "outline"}
            aria-pressed={preview === p.key}
            onClick={() => setPreview(p.key)}
          >
            {p.label}
          </Button>
        ))}
      </div>

      {/* Filters */}
      <div style={{ display: "flex", flexDirection: "column", gap: "var(--atlas-spacing-2)" }}>
        <Input
          size="md"
          type="search"
          aria-label="Search invoices"
          placeholder="Search invoice or customer"
          leadingIcon={<SearchIcon aria-hidden size={16} />}
          value={query}
          onChange={(e) => setQuery(e.target.value)}
        />
        <Select value={status} onValueChange={(v) => setStatus(v as StatusFilter)}>
          <SelectTrigger size="md" aria-label="Filter by status">
            <SelectValue placeholder="Status" />
          </SelectTrigger>
          <SelectContent>
            {STATUS_FILTERS.map((s) => (
              <SelectItem key={s} value={s}>
                {s === "all" ? "All statuses" : s}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>
      </div>

      {/* Bulk action bar */}
      {count > 0 && !loading && (
        <div
          role="region"
          aria-label="Bulk actions"
          style={{
            display: "flex",
            alignItems: "center",
            justifyContent: "space-between",
            gap: "var(--atlas-spacing-2)",
            padding: "var(--atlas-spacing-2) var(--atlas-spacing-3)",
            background: "var(--atlas-surface-raised)",
            border: "var(--atlas-border-width-1) solid var(--atlas-border)",
            borderRadius: "var(--atlas-radius-md)",
            boxShadow: "var(--atlas-shadow-md)",
          }}
        >
          <span
            aria-live="polite"
            style={{ fontSize: "var(--atlas-font-size-sm)", fontWeight: "var(--atlas-font-weight-medium)" }}
          >
            {count} selected
          </span>
          <div style={{ display: "flex", gap: "var(--atlas-spacing-2)" }}>
            <Button size="sm" variant="secondary" onClick={markPaid}>
              Mark as paid
            </Button>
            <Button size="sm" variant="destructive" onClick={() => setConfirmOpen(true)}>
              Delete
            </Button>
          </div>
        </div>
      )}

      {/* Table (scrolls horizontally inside the phone frame) */}
      <div
        aria-busy={loading}
        style={{
          overflowX: "auto",
          border: "var(--atlas-border-width-1) solid var(--atlas-border)",
          borderRadius: "var(--atlas-radius-md)",
        }}
      >
        <div style={{ minWidth: "var(--atlas-container-sm)" }}>
          <Table>
            <TableHeader>
              <TableRow>
                <TableHead style={{ width: "var(--atlas-spacing-10)" }}>
                  <Checkbox
                    size="sm"
                    aria-label="Select all invoices"
                    checked={allChecked}
                    disabled={loading || visible.length === 0}
                    onCheckedChange={toggleAll}
                  />
                </TableHead>
                <TableHead>Invoice</TableHead>
                <TableHead>Customer</TableHead>
                <TableHead align="end">Amount</TableHead>
                <TableHead>Status</TableHead>
                <TableHead>Due</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {loading &&
                SKELETON_ROWS.map((i) => (
                  <TableRow key={i}>
                    {[0, 1, 2, 3, 4, 5].map((c) => (
                      <TableCell key={c}>
                        <Skeleton />
                      </TableCell>
                    ))}
                  </TableRow>
                ))}
              {!loading &&
                visible.map((inv) => (
                  <TableRow key={inv.id} selected={selected.has(inv.id)}>
                    <TableCell>
                      <Checkbox
                        size="sm"
                        aria-label={`Select ${inv.number}`}
                        checked={selected.has(inv.id)}
                        onCheckedChange={(c) => toggleRow(inv.id, c)}
                      />
                    </TableCell>
                    <TableCell>{inv.number}</TableCell>
                    <TableCell>{inv.customer}</TableCell>
                    <TableCell align="end">{formatAmount(inv.amount)}</TableCell>
                    <TableCell>
                      <Badge variant={STATUS_BADGE[inv.status]} size="sm" dot>
                        {inv.status}
                      </Badge>
                    </TableCell>
                    <TableCell>{formatDue(inv.due)}</TableCell>
                  </TableRow>
                ))}
            </TableBody>
          </Table>
        </div>

        {!loading && visible.length === 0 && (
          <div
            role="status"
            style={{
              display: "flex",
              flexDirection: "column",
              alignItems: "center",
              gap: "var(--atlas-spacing-2)",
              padding: "var(--atlas-spacing-8) var(--atlas-spacing-4)",
              textAlign: "center",
              position: "sticky",
              insetInlineStart: 0,
              maxInlineSize: "100%",
              boxSizing: "border-box",
            }}
          >
            <FileSearchIcon aria-hidden size={32} color="var(--atlas-foreground-subtle)" />
            <p
              style={{
                margin: 0,
                fontSize: "var(--atlas-font-size-base)",
                fontWeight: "var(--atlas-font-weight-semibold)",
              }}
            >
              {noInvoicesAtAll ? "No invoices" : "No invoices match your filters"}
            </p>
            <p style={{ margin: 0, fontSize: "var(--atlas-font-size-sm)", color: "var(--atlas-foreground-muted)" }}>
              {noInvoicesAtAll
                ? "Use Reset in the header to restore the sample data."
                : "Try a different search or status."}
            </p>
            {!noInvoicesAtAll && (
              <Button size="sm" variant="outline" onClick={clearFilters}>
                Clear filters
              </Button>
            )}
          </div>
        )}
      </div>

      <AlertDialog open={confirmOpen} onOpenChange={setConfirmOpen}>
        <AlertDialogContent variant="destructive" size="sm">
          <AlertDialogTitle>
            Delete {count} {count === 1 ? "invoice" : "invoices"}?
          </AlertDialogTitle>
          <AlertDialogDescription>
            This permanently removes the selected {count === 1 ? "invoice" : "invoices"}. This can&apos;t be undone.
          </AlertDialogDescription>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <AlertDialogAction onClick={deleteSelected}>Delete</AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  )
}

